def carregar(nome):
    with open(os.path.join(RAIZ, "app", "biblia", nome), encoding="utf-8") as f:
        return json.load(f)


def ref_ok(ref, biblias):
    m = re.fullmatch(r"(\d+)\.(\d+)\.(\d+)(?:-(\d+))?", ref)
    if not m:
        return "formato inválido"
    b, c, v1 = int(m[1]), int(m[2]), int(m[3])
    v2 = int(m[4]) if m[4] else v1
    if b not in LIVROS_OK:
        return "livro fora da cota (5-16, 40, 41)"
    if v2 < v1 or v2 - v1 > 2:
        return "intervalo inválido (1 a 3 versículos)"
    for nome, bib in biblias.items():
        try:
            cap = bib[b][c - 1]
            if c < 1 or v1 < 1 or v2 > len(cap):
                return "não existe em " + nome
        except IndexError:
            return "não existe em " + nome
    return None


def palavras(s):
    return len(s.split())


PROIBIDO_ES = re.compile(r"(?<![\wáéíóúñü])(tú|tu|tienes|puedes)(?![\wáéíóúñü])", re.I)


def main():
    biblias = {"pt-livre": carregar("pt-livre.json"), "es-rv1909": carregar("es-rv1909.json")}
    erros, vistos = [], set()
    for i, d in enumerate(D):
        dia = DIA_INICIAL + i
        p = "dia %d (%s)" % (dia, d.get("v"))
        if set(d) != {"t", "v", "r", "a", "o"}:
            erros.append(p + ": chaves erradas")
            continue
        e = ref_ok(d["v"], biblias)
        if e:
            erros.append(p + ": " + e)
        if d["v"] in vistos:
            erros.append(p + ": referência repetida")
        vistos.add(d["v"])
        for k in "tra o".replace(" ", ""):
            if not (isinstance(d[k], list) and len(d[k]) == 2 and all(isinstance(x, str) and x.strip() for x in d[k])):
                erros.append(p + ": campo %s precisa ser [ES, PT]" % k)
        for lang, idx in (("ES", 0), ("PT", 1)):
            n = palavras(d["t"][idx])
            if not 2 <= n <= 6:
                erros.append("%s: título %s com %d palavras" % (p, lang, n))
            n = palavras(d["r"][idx])
            if not 90 <= n <= 140:
                erros.append("%s: reflexão %s com %d palavras" % (p, lang, n))
            n = palavras(d["o"][idx])
            if not 30 <= n <= 60:
                erros.append("%s: oração %s com %d palavras" % (p, lang, n))
        if not d["o"][0].endswith("En el nombre de Jesús, amén."):
            erros.append(p + ": oração ES sem fechamento")
        if not d["o"][1].endswith("Em nome de Jesus, amém."):
            erros.append(p + ": oração PT sem fechamento")
        for k in "tra o".replace(" ", ""):
            m = PROIBIDO_ES.search(d[k][0])
            if m:
                erros.append("%s: ES usa '%s' em %s (use usted)" % (p, m[0], k))
    if len(D) != TOTAL:
        erros.append("total %d, esperado %d" % (len(D), TOTAL))
    if erros:
        print("\n".join(erros))
        print("%d erro(s)" % len(erros))
        sys.exit(1)
    saida = os.path.join(AQUI, "devocional-2.json")
    with open(saida, "w", encoding="utf-8") as f:
        json.dump(D, f, ensure_ascii=False, separators=(",", ":"))
    print("OK: %d devocionais (dias %d-%d) gravados em %s" % (len(D), DIA_INICIAL, DIA_INICIAL + len(D) - 1, saida))


if __name__ == "__main__":
    main()
